        'https://yoclip.studio/oauth/openrouter.html',
      );
      expect(custom.webAppCallbackUrl, 'https://yoclip.studio/app/index.html');
      expect(
        custom.nativeCallbackUrl,
        'https://yoclip.studio/oauth/openrouter-native.html',
